import bisect
class ConsistentHash:
    def __init__(self, replicas):
        self.replicas = replicas
        self.keys = []          # sorted ring positions
        self.ring = {}          # position -> server
    def add_server(self, s):
        for i in range(self.replicas):
            h = hash_fn(f"{s}#{i}")            # virtual nodes
            bisect.insort(self.keys, h)
            self.ring[h] = s
    def get_server(self, key):
        h = hash_fn(key)
        idx = bisect.bisect_left(self.keys, h)   # first position >= h
        if idx == len(self.keys):
            idx = 0                              # wrap around
        return self.ring[self.keys[idx]]

