class ConsistentHash {
    TreeMap<Integer, String> ring = new TreeMap<>();   // sorted ring positions
    int replicas;
    ConsistentHash(int r) { replicas = r; }
    void addServer(String s) {
        for (int i = 0; i < replicas; i++)
            ring.put(hashFn(s + "#" + i), s);   // virtual nodes
    }
    String getServer(String key) {
        int h = hashFn(key);
        Map.Entry<Integer, String> e = ring.ceilingEntry(h);   // first position >= h
        if (e == null) e = ring.firstEntry();                   // wrap around
        return e.getValue();
    }
}

