class ConsistentHash {
  constructor(replicas) { this.replicas = replicas; this.keys = []; this.ring = new Map(); }
  addServer(s) {
    for (let i = 0; i < this.replicas; i++) {
      const h = hashFn(s + '#' + i);          // virtual nodes
      const idx = this._bisect(h);
      this.keys.splice(idx, 0, h);
      this.ring.set(h, s);
    }
  }
  getServer(key) {
    const h = hashFn(key);
    let idx = this._bisect(h);                 // first position >= h
    if (idx === this.keys.length) idx = 0;     // wrap around
    return this.ring.get(this.keys[idx]);
  }
  _bisect(h) { let lo = 0, hi = this.keys.length; while (lo < hi) { const m = (lo + hi) >> 1; if (this.keys[m] < h) lo = m + 1; else hi = m; } return lo; }
}
